const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  var utah = ee.FeatureCollection('TIGER/2018/States')
    .filter(ee.Filter.eq('NAME', 'Utah'));

  var aug2020 = ee.DateRange('2020-08-01', '2020-08-31');
  var longTerm = ee.DateRange('2015-08-01', '2019-08-31');

  // 2. Data Acquisition
  var smap = ee.ImageCollection('NASA_USDA/HSL/SMAP10KM_soil_moisture')
    .select('ssm');

  var aug2020Col = smap.filterBounds(utah).filterDate(aug2020);
  var longTermCol = smap.filterBounds(utah).filterDate(longTerm);

  var aug2020Count = aug2020Col.size().getInfo();
  var longTermCount = longTermCol.size().getInfo();

  print(`2020 August Images: ${aug2020Count}`);
  print(`Long-term August Images: ${longTermCount}`);

  // Check for empty collections
  if (aug2020Count === 0 || longTermCount === 0) {
    print("<answer>C1</answer>");
    return;
  }

  // 3. Processing - Calculate mean soil moisture
  var aug2020Mean = aug2020Col.mean();
  var longTermMean = longTermCol.mean();

  // Check valid pixels
  var aug2020Stats = aug2020Mean.reduceRegion({
    reducer: ee.Reducer.count().combine(ee.Reducer.mean(), null, true),
    geometry: utah,
    scale: 10000,
    maxPixels: 1e9
  }).getInfo();

  var longTermStats = longTermMean.reduceRegion({
    reducer: ee.Reducer.count().combine(ee.Reducer.mean(), null, true),
    geometry: utah,
    scale: 10000,
    maxPixels: 1e9
  }).getInfo();

  var aug2020Pixels = aug2020Stats.ssm_count;
  var longTermPixels = longTermStats.ssm_count;
  var aug2020SM = aug2020Stats.ssm_mean;
  var longTermSM = longTermStats.ssm_mean;

  print(`2020 Valid Pixels: ${aug2020Pixels}, SM: ${aug2020SM ? aug2020SM.toFixed(3) : 'null'}`);
  print(`Long-term Valid Pixels: ${longTermPixels}, SM: ${longTermSM ? longTermSM.toFixed(3) : 'null'}`);

  // Check for no valid pixels
  if (aug2020Pixels === 0 || longTermPixels === 0) {
    print("<answer>C2</answer>");
    return;
  }

  // 4. Validation & Final Answer
  if (aug2020SM === null || longTermSM === null || 
      aug2020SM < 0 || aug2020SM > 100 || 
      longTermSM < 0 || longTermSM > 100) {
    print("<answer>C3</answer>");
    return;
  }

  // Compare soil moisture values
  if (aug2020SM < longTermSM) {
    print("<answer>A</answer>");
  } else {
    print("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
